import Quiz from '../models/Quiz.js';
import Attempt from '../models/Attempt.js';

// POST /api/classes/:classGroupId/attempts  (approved student) - submit answers, auto-graded
// body: { quizId, answers: [optionIndex, ...] }
export async function submitAttempt(req, res) {
  const { quizId, answers } = req.body;
  if (!quizId || !Array.isArray(answers)) {
    return res.status(400).json({ message: 'quizId and answers[] are required' });
  }

  const quiz = await Quiz.findOne({ _id: quizId, classGroup: req.classGroupId, published: true });
  if (!quiz) return res.status(404).json({ message: 'Quiz not found or not published' });

  const already = await Attempt.findOne({ quiz: quizId, student: req.user._id });
  if (already) return res.status(409).json({ message: 'You have already attempted this quiz' });

  let correct = 0;
  quiz.questions.forEach((q, i) => {
    if (answers[i] === q.correctIndex) correct += 1;
  });
  const score = quiz.questions.length ? Math.round((correct / quiz.questions.length) * 100) : 0;

  const attempt = await Attempt.create({
    quiz: quizId,
    student: req.user._id,
    answers,
    score,
  });

  res.status(201).json({ score, correct, total: quiz.questions.length, attempt });
}

// GET /api/classes/:classGroupId/attempts/me/progress  (approved student) - subject progress chart data, this class only
// Returns: { "Pure Maths": [{order, score, title}], "Applied Maths": [...], ... }
export async function getMyProgress(req, res) {
  const quizzesInClass = await Quiz.find({ classGroup: req.classGroupId }).select('_id');
  const quizIds = quizzesInClass.map((q) => q._id);

  const attempts = await Attempt.find({ student: req.user._id, quiz: { $in: quizIds } }).populate(
    'quiz',
    'subject order title'
  );

  const bySubject = {};
  for (const a of attempts) {
    if (!a.quiz) continue;
    const subject = a.quiz.subject;
    if (!bySubject[subject]) bySubject[subject] = [];
    bySubject[subject].push({ order: a.quiz.order, title: a.quiz.title, score: a.score });
  }
  Object.values(bySubject).forEach((list) => list.sort((x, y) => x.order - y.order));

  res.json(bySubject);
}

import Attendance from '../models/Attendance.js';
import Session from '../models/Session.js';
import { calculateAttendancePercentage } from '../utils/attendanceStats.js';

// GET /api/classes/:classGroupId/attendance/session/:sessionId  (owner teacher) - all students' marks for one session
export async function getBySession(req, res) {
  const session = await Session.findOne({ _id: req.params.sessionId, classGroup: req.classGroupId });
  if (!session) return res.status(404).json({ message: 'Session not found in this class' });

  const records = await Attendance.find({ session: session._id }).populate('student', 'name email');
  res.json(records);
}

// GET /api/classes/:classGroupId/attendance/me  (approved student) - this student's history + % within THIS class only
export async function getMyAttendance(req, res) {
  const sessions = await Session.find({ classGroup: req.classGroupId }).select('_id');
  const sessionIds = sessions.map((s) => s._id);

  const records = await Attendance.find({ student: req.user._id, session: { $in: sessionIds } })
    .populate('session', 'date topic')
    .sort({ createdAt: -1 });

  res.json({ records, summary: calculateAttendancePercentage(records) });
}

// POST /api/classes/:classGroupId/attendance  (owner teacher) - mark/update one student's attendance for a session
// body: { sessionId, studentId, status }
export async function markAttendance(req, res) {
  const { sessionId, studentId, status } = req.body;
  if (!sessionId || !studentId || !status) {
    return res.status(400).json({ message: 'sessionId, studentId and status are required' });
  }
  if (!['present', 'late', 'absent'].includes(status)) {
    return res.status(400).json({ message: 'status must be present, late or absent' });
  }

  const session = await Session.findOne({ _id: sessionId, classGroup: req.classGroupId });
  if (!session) return res.status(404).json({ message: 'Session not found in this class' });

  const record = await Attendance.findOneAndUpdate(
    { session: sessionId, student: studentId },
    { status, markedAt: new Date() },
    { new: true, upsert: true }
  );
  res.json(record);
}

import User from '../models/User.js';
import { generateToken } from '../utils/generateToken.js';

function sanitize(user) {
  return {
    id: user._id,
    name: user.name,
    email: user.email,
    role: user.role,
    grade: user.grade,
  };
}

// POST /api/auth/register
// Just creates the account. A teacher then creates their own class(es) via
// POST /api/classes; a student browses published classes (GET /api/classes/published)
// and requests a seat in each one they want (POST /api/classes/:id/enroll).
export async function register(req, res) {
  const { name, email, password, role, grade } = req.body;
  if (!name || !email || !password || !role) {
    return res.status(400).json({ message: 'name, email, password and role are required' });
  }
  if (!['teacher', 'student'].includes(role)) {
    return res.status(400).json({ message: 'role must be teacher or student' });
  }

  const existing = await User.findOne({ email: email.toLowerCase() });
  if (existing) {
    return res.status(409).json({ message: 'An account with this email already exists' });
  }

  const user = await User.create({
    name,
    email,
    password,
    role,
    grade: role === 'student' ? grade || null : null,
  });

  const token = generateToken(user);
  res.status(201).json({ token, user: sanitize(user) });
}

// POST /api/auth/login
export async function login(req, res) {
  const { email, password, role } = req.body;
  if (!email || !password) {
    return res.status(400).json({ message: 'email and password are required' });
  }

  const user = await User.findOne({ email: email.toLowerCase() }).select('+password');
  if (!user) {
    return res.status(401).json({ message: 'Invalid email or password' });
  }
  if (role && user.role !== role) {
    return res.status(401).json({ message: `This account is not registered as a ${role}` });
  }

  const match = await user.comparePassword(password);
  if (!match) {
    return res.status(401).json({ message: 'Invalid email or password' });
  }

  const token = generateToken(user);
  res.json({ token, user: sanitize(user) });
}

// GET /api/auth/me
export async function me(req, res) {
  res.json({ user: sanitize(req.user) });
}

import ClassGroup from '../models/ClassGroup.js';
import Enrollment from '../models/Enrollment.js';

function classSummary(classGroup) {
  return {
    id: classGroup._id,
    name: classGroup.name,
    grade: classGroup.grade,
    subjects: classGroup.subjects,
    description: classGroup.description,
    schedule: classGroup.schedule,
    monthlyFee: classGroup.monthlyFee,
    maxStudents: classGroup.maxStudents,
    coverImageUrl: classGroup.coverImageUrl,
    published: classGroup.published,
    teacher: classGroup.teacher,
    createdAt: classGroup.createdAt,
  };
}

// POST /api/classes  (teacher) - create a new class they'll own
export async function createClass(req, res) {
  const { name, grade, subjects, description, schedule, monthlyFee, maxStudents, published } = req.body;
  if (!name) return res.status(400).json({ message: 'name is required' });

  const classGroup = await ClassGroup.create({
    name,
    teacher: req.user._id,
    grade: grade || '',
    subjects: Array.isArray(subjects) ? subjects.filter(Boolean) : [],
    description: description || '',
    schedule: schedule || 'Sat-Sun, 2:00-6:00 PM',
    monthlyFee: monthlyFee || 3000,
    maxStudents: maxStudents || 15,
    published: Boolean(published),
  });
  res.status(201).json(classSummary(classGroup));
}

// GET /api/classes/mine  (teacher) - every class this teacher owns, with enrollment counts
export async function listMyClasses(req, res) {
  const classes = await ClassGroup.find({ teacher: req.user._id }).sort({ createdAt: -1 });

  const withCounts = await Promise.all(
    classes.map(async (c) => {
      const approvedCount = await Enrollment.countDocuments({ classGroup: c._id, status: 'approved' });
      const pendingCount = await Enrollment.countDocuments({ classGroup: c._id, status: 'pending' });
      return { ...classSummary(c), approvedCount, pendingCount };
    })
  );
  res.json(withCounts);
}

// GET /api/classes/enrolled  (student) - every class this student has requested/joined, with status
export async function listEnrolledClasses(req, res) {
  const enrollments = await Enrollment.find({ student: req.user._id }).populate({
    path: 'classGroup',
    populate: { path: 'teacher', select: 'name' },
  });

  const results = enrollments
    .filter((e) => e.classGroup) // guard against a class that was since removed
    .map((e) => ({
      ...classSummary(e.classGroup),
      teacherName: e.classGroup.teacher?.name || 'Unknown teacher',
      enrollmentId: e._id,
      enrollmentStatus: e.status,
    }));
  res.json(results);
}

// GET /api/classes/published  (student) - classes open to browse & request, excluding ones already requested
export async function listPublishedClasses(req, res) {
  const classes = await ClassGroup.find({ published: true })
    .populate('teacher', 'name')
    .sort({ createdAt: -1 });

  const myEnrollments = await Enrollment.find({ student: req.user._id });
  const statusByClass = new Map(myEnrollments.map((e) => [String(e.classGroup), e.status]));

  const results = classes.map((c) => ({
    ...classSummary(c),
    teacherName: c.teacher?.name || 'Unknown teacher',
    enrollmentStatus: statusByClass.get(String(c._id)) || null, // null = not requested yet
  }));
  res.json(results);
}

// GET /api/classes/:classGroupId  (owner teacher, approved/pending student, or anyone if published)
export async function getClass(req, res) {
  const classGroup = req.targetClass;
  const isOwner = String(classGroup.teacher) === String(req.user._id);

  if (!isOwner && !classGroup.published) {
    const enrollment = req.user.role === 'student'
      ? await Enrollment.findOne({ student: req.user._id, classGroup: classGroup._id })
      : null;
    if (!enrollment) return res.status(403).json({ message: 'This class is not published' });
  }

  await classGroup.populate('teacher', 'name email');
  res.json({ ...classSummary(classGroup), teacherName: classGroup.teacher?.name });
}

// PATCH /api/classes/:classGroupId  (owner teacher only)
export async function updateClass(req, res) {
  const allowed = ['name', 'grade', 'subjects', 'description', 'schedule', 'monthlyFee', 'maxStudents', 'published', 'coverImageUrl'];
  const updates = {};
  allowed.forEach((key) => {
    if (req.body[key] !== undefined) updates[key] = req.body[key];
  });

  const classGroup = await ClassGroup.findByIdAndUpdate(req.targetClass._id, updates, { new: true });
  res.json(classSummary(classGroup));
}

// POST /api/classes/:classGroupId/enroll  (student) - request a seat
export async function requestEnrollment(req, res) {
  const classGroup = req.targetClass;
  if (!classGroup.published) {
    return res.status(404).json({ message: 'This class is not open for enrollment' });
  }

  let enrollment = await Enrollment.findOne({ student: req.user._id, classGroup: classGroup._id });
  if (enrollment) {
    if (enrollment.status === 'approved') {
      return res.status(409).json({ message: 'You are already enrolled in this class' });
    }
    if (enrollment.status === 'pending') {
      return res.status(409).json({ message: 'Your request is already pending approval' });
    }
    // Previously rejected - let them ask again.
    enrollment.status = 'pending';
    enrollment.requestedAt = new Date();
    enrollment.respondedAt = null;
    await enrollment.save();
  } else {
    enrollment = await Enrollment.create({ student: req.user._id, classGroup: classGroup._id });
  }
  res.status(201).json({ id: enrollment._id, status: enrollment.status });
}

// GET /api/classes/:classGroupId/enrollments  (owner teacher) - pending first, then approved/rejected
export async function listEnrollments(req, res) {
  const enrollments = await Enrollment.find({ classGroup: req.targetClass._id })
    .populate('student', 'name email grade')
    .sort({ requestedAt: -1 });

  // Pending requests need attention first; stable sort keeps requestedAt order within each group.
  const order = { pending: 0, approved: 1, rejected: 2 };
  enrollments.sort((a, b) => order[a.status] - order[b.status]);

  res.json(
    enrollments.map((e) => ({
      id: e._id,
      status: e.status,
      requestedAt: e.requestedAt,
      respondedAt: e.respondedAt,
      student: e.student ? { id: e.student._id, name: e.student.name, email: e.student.email, grade: e.student.grade } : null,
    }))
  );
}

// PATCH /api/classes/:classGroupId/enrollments/:enrollmentId  (owner teacher) - approve or reject
export async function respondToEnrollment(req, res) {
  const { status } = req.body;
  if (!['approved', 'rejected'].includes(status)) {
    return res.status(400).json({ message: 'status must be approved or rejected' });
  }

  const enrollment = await Enrollment.findOneAndUpdate(
    { _id: req.params.enrollmentId, classGroup: req.targetClass._id },
    { status, respondedAt: new Date() },
    { new: true }
  ).populate('student', 'name email grade');

  if (!enrollment) return res.status(404).json({ message: 'Enrollment request not found' });
  res.json(enrollment);
}

import Material from '../models/Material.js';
import fs from 'fs';
import path from 'path';

// GET /api/materials
export async function listMaterials(req, res) {
  const materials = await Material.find({ classGroup: req.classGroupId }).sort({ createdAt: -1 });
  res.json(materials);
}

// POST /api/materials  (teacher only) - multipart/form-data, field name "file"
export async function uploadMaterial(req, res) {
  const { title, subject } = req.body;
  if (!req.file) return res.status(400).json({ message: 'A file is required' });
  if (!title || !subject) return res.status(400).json({ message: 'title and subject are required' });

  const material = await Material.create({
    classGroup: req.classGroupId,
    title,
    subject,
    fileUrl: `/uploads/${req.file.filename}`,
    fileName: req.file.originalname,
    uploadedBy: req.user._id,
  });
  res.status(201).json(material);
}

// DELETE /api/materials/:id  (teacher only)
export async function deleteMaterial(req, res) {
  const material = await Material.findOneAndDelete({ _id: req.params.id, classGroup: req.classGroupId });
  if (!material) return res.status(404).json({ message: 'Material not found' });

  const filePath = path.resolve('src' + material.fileUrl);
  fs.unlink(filePath, () => {}); // best-effort cleanup, ignore errors

  res.json({ message: 'Material deleted' });
}

