import Payment from '../models/Payment.js';
import Enrollment from '../models/Enrollment.js';

// GET /api/classes/:classGroupId/payments/me  (approved student) - this student's payments, this class only
export async function getMyPayments(req, res) {
  const payments = await Payment.find({ student: req.user._id, classGroup: req.classGroupId }).sort({ month: -1 });
  res.json(payments);
}

// GET /api/classes/:classGroupId/payments  (owner teacher) - every approved student's payment for a given month
export async function listPayments(req, res) {
  const month = req.query.month || new Date().toISOString().slice(0, 7);
  const payments = await Payment.find({ classGroup: req.classGroupId, month }).populate('student', 'name email');
  res.json(payments);
}

// POST /api/classes/:classGroupId/payments/generate  (owner teacher)
// Creates this month's "due" record for every approved student who doesn't have one yet.
export async function generateMonthlyPayments(req, res) {
  const month = req.body.month || new Date().toISOString().slice(0, 7);
  const classGroup = req.targetClass;

  const approved = await Enrollment.find({ classGroup: req.classGroupId, status: 'approved' }).select('student');
  const dueDate = new Date(`${month}-05`);

  const created = [];
  for (const { student } of approved) {
    const existing = await Payment.findOne({ student, classGroup: req.classGroupId, month });
    if (existing) continue;
    const payment = await Payment.create({
      student,
      classGroup: req.classGroupId,
      month,
      amount: classGroup.monthlyFee,
      status: 'due',
      dueDate,
    });
    created.push(payment);
  }
  res.status(201).json({ createdCount: created.length, payments: created });
}

// PATCH /api/classes/:classGroupId/payments/:id  (owner teacher) - mark paid / due / overdue
export async function updatePayment(req, res) {
  const { status } = req.body;
  if (!['paid', 'due', 'overdue'].includes(status)) {
    return res.status(400).json({ message: 'status must be paid, due or overdue' });
  }
  const payment = await Payment.findOneAndUpdate(
    { _id: req.params.id, classGroup: req.classGroupId },
    { status, paidAt: status === 'paid' ? new Date() : null },
    { new: true }
  );
  if (!payment) return res.status(404).json({ message: 'Payment not found' });
  res.json(payment);
}

import Quiz from '../models/Quiz.js';
import Attempt from '../models/Attempt.js';

function stripAnswers(quiz, forStudent) {
  const obj = quiz.toObject();
  if (forStudent) {
    obj.questions = obj.questions.map(({ text, options }) => ({ text, options }));
  }
  return obj;
}

// GET /api/quizzes  (both roles; students only see published quizzes)
export async function listQuizzes(req, res) {
  const filter = { classGroup: req.classGroupId };
  if (req.user.role === 'student') filter.published = true;

  const quizzes = await Quiz.find(filter).sort({ dueDate: 1 });

  if (req.user.role === 'student') {
    const attempts = await Attempt.find({ student: req.user._id, quiz: { $in: quizzes.map((q) => q._id) } });
    const attemptedIds = new Set(attempts.map((a) => String(a.quiz)));
    return res.json(
      quizzes.map((q) => ({ ...stripAnswers(q, true), attempted: attemptedIds.has(String(q._id)) }))
    );
  }

  // teacher view: include attempt counts
  const withCounts = await Promise.all(
    quizzes.map(async (q) => {
      const attemptCount = await Attempt.countDocuments({ quiz: q._id });
      return { ...q.toObject(), attemptCount };
    })
  );
  res.json(withCounts);
}

// GET /api/quizzes/:id
export async function getQuiz(req, res) {
  const quiz = await Quiz.findOne({ _id: req.params.id, classGroup: req.classGroupId });
  if (!quiz) return res.status(404).json({ message: 'Quiz not found' });
  if (req.user.role === 'student' && !quiz.published) {
    return res.status(403).json({ message: 'This quiz is not published yet' });
  }
  res.json(req.user.role === 'student' ? stripAnswers(quiz, true) : quiz);
}

// POST /api/quizzes  (teacher only)
export async function createQuiz(req, res) {
  const { title, subject, order, dueDate, durationMinutes, questions, published } = req.body;
  if (!title || !subject || !dueDate) {
    return res.status(400).json({ message: 'title, subject and dueDate are required' });
  }
  const quiz = await Quiz.create({
    classGroup: req.classGroupId,
    title,
    subject,
    order: order || 1,
    dueDate,
    durationMinutes: durationMinutes || 20,
    questions: questions || [],
    published: Boolean(published),
  });
  res.status(201).json(quiz);
}

// PATCH /api/quizzes/:id  (teacher only)
export async function updateQuiz(req, res) {
  const quiz = await Quiz.findOneAndUpdate(
    { _id: req.params.id, classGroup: req.classGroupId },
    req.body,
    { new: true }
  );
  if (!quiz) return res.status(404).json({ message: 'Quiz not found' });
  res.json(quiz);
}

// DELETE /api/quizzes/:id  (teacher only)
export async function deleteQuiz(req, res) {
  const quiz = await Quiz.findOneAndDelete({ _id: req.params.id, classGroup: req.classGroupId });
  if (!quiz) return res.status(404).json({ message: 'Quiz not found' });
  res.json({ message: 'Quiz deleted' });
}

