import Enrollment from '../models/Enrollment.js';
import Attendance from '../models/Attendance.js';
import Payment from '../models/Payment.js';
import Quiz from '../models/Quiz.js';
import Session from '../models/Session.js';

// GET /api/classes/:classGroupId/stats/student  (student, approved in this class)
export async function studentStats(req, res) {
  const sessions = await Session.find({ classGroup: req.classGroupId }).select('_id');
  const sessionIds = sessions.map((s) => s._id);

  const records = await Attendance.find({ student: req.user._id, session: { $in: sessionIds } });
  const total = records.length;
  const present = records.filter((r) => r.status === 'present' || r.status === 'late').length;
  const attendancePct = total ? Math.round((present / total) * 100) : 0;

  const month = new Date().toISOString().slice(0, 7);
  const payment = await Payment.findOne({ student: req.user._id, classGroup: req.classGroupId, month });

  const upcomingQuizzes = await Quiz.find({
    classGroup: req.classGroupId,
    published: true,
    dueDate: { $gte: new Date() },
  })
    .sort({ dueDate: 1 })
    .limit(5);

  res.json({
    attendancePct,
    feeDue: payment ? { amount: payment.amount, status: payment.status, dueDate: payment.dueDate } : null,
    upcomingQuizCount: upcomingQuizzes.length,
    nextQuiz: upcomingQuizzes[0] || null,
  });
}

// GET /api/classes/:classGroupId/stats/admin  (owner teacher)
export async function adminStats(req, res) {
  const totalStudents = await Enrollment.countDocuments({ classGroup: req.classGroupId, status: 'approved' });
  const pendingRequests = await Enrollment.countDocuments({ classGroup: req.classGroupId, status: 'pending' });

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);

  const todaySession = await Session.findOne({
    classGroup: req.classGroupId,
    date: { $gte: today, $lt: tomorrow },
  });

  let todayAttendancePct = 0;
  if (todaySession) {
    const records = await Attendance.find({ session: todaySession._id });
    const present = records.filter((r) => r.status === 'present' || r.status === 'late').length;
    todayAttendancePct = totalStudents ? Math.round((present / totalStudents) * 100) : 0;
  }

  const month = new Date().toISOString().slice(0, 7);
  const payments = await Payment.find({ classGroup: req.classGroupId, month });
  const pending = payments.filter((p) => p.status !== 'paid');
  const pendingAmount = pending.reduce((sum, p) => sum + p.amount, 0);

  const activeQuizzes = await Quiz.countDocuments({
    classGroup: req.classGroupId,
    published: true,
    dueDate: { $gte: new Date() },
  });

  res.json({
    totalStudents,
    pendingRequests,
    todayAttendancePct,
    hasSessionToday: Boolean(todaySession),
    pendingPaymentsCount: pending.length,
    pendingPaymentsAmount: pendingAmount,
    activeQuizzes,
  });
}

import Enrollment from '../models/Enrollment.js';
import Attendance from '../models/Attendance.js';
import Payment from '../models/Payment.js';
import Session from '../models/Session.js';

// GET /api/classes/:classGroupId/students  (owner teacher) - every APPROVED student in this class,
// with their attendance % and this month's payment status, scoped to this class only.
export async function listStudents(req, res) {
  const enrollments = await Enrollment.find({ classGroup: req.classGroupId, status: 'approved' }).populate(
    'student',
    'name email grade'
  );

  const sessions = await Session.find({ classGroup: req.classGroupId }).select('_id');
  const sessionIds = sessions.map((s) => s._id);

  const month = new Date().toISOString().slice(0, 7);

  const results = await Promise.all(
    enrollments
      .filter((e) => e.student)
      .map(async (e) => {
        const s = e.student;
        const total = await Attendance.countDocuments({ student: s._id, session: { $in: sessionIds } });
        const present = await Attendance.countDocuments({
          student: s._id,
          session: { $in: sessionIds },
          status: { $in: ['present', 'late'] },
        });
        const attendancePct = total ? Math.round((present / total) * 100) : 0;

        const payment = await Payment.findOne({ student: s._id, classGroup: req.classGroupId, month });

        return {
          id: s._id,
          name: s.name,
          email: s.email,
          grade: s.grade,
          attendancePct,
          paymentStatus: payment ? payment.status : 'due',
        };
      })
  );

  res.json(results);
}

// GET /api/classes/:classGroupId/students/:id  (owner teacher) - one approved student's basic info
export async function getStudent(req, res) {
  const enrollment = await Enrollment.findOne({
    classGroup: req.classGroupId,
    student: req.params.id,
    status: 'approved',
  }).populate('student', 'name email grade');
  if (!enrollment || !enrollment.student) {
    return res.status(404).json({ message: 'Student not found in this class' });
  }
  res.json(enrollment.student);
}

import jwt from 'jsonwebtoken';
import User from '../models/User.js';

export async function protect(req, res, next) {
  try {
    const header = req.headers.authorization;
    if (!header || !header.startsWith('Bearer ')) {
      return res.status(401).json({ message: 'Not authorized, no token' });
    }
    const token = header.split(' ')[1];
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    const user = await User.findById(decoded.id);
    if (!user) {
      return res.status(401).json({ message: 'Not authorized, user no longer exists' });
    }
    req.user = user;
    next();
  } catch (err) {
    return res.status(401).json({ message: 'Not authorized, token failed' });
  }
}

export function allowRoles(...roles) {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ message: 'Forbidden: insufficient role' });
    }
    next();
  };
}

import ClassGroup from '../models/ClassGroup.js';
import Enrollment from '../models/Enrollment.js';

/**
 * Every class-scoped route is mounted under /api/classes/:classGroupId/...
 * This middleware loads that class once and attaches it to req.targetClass,
 * so the guards below (and the controllers) don't each re-fetch it.
 */
export async function loadClassGroup(req, res, next) {
  try {
    const classGroup = await ClassGroup.findById(req.params.classGroupId);
    if (!classGroup) return res.status(404).json({ message: 'Class not found' });
    req.targetClass = classGroup;
    req.classGroupId = classGroup._id;
    next();
  } catch (err) {
    next(err);
  }
}

/** Teacher-only write actions: you must be the teacher who owns this class. */
export function requireOwnerTeacher(req, res, next) {
  if (String(req.targetClass.teacher) !== String(req.user._id)) {
    return res.status(403).json({ message: 'You do not own this class' });
  }
  next();
}

/** Student-only actions that require an approved seat in this class. */
export async function requireApprovedStudent(req, res, next) {
  try {
    const enrollment = await Enrollment.findOne({
      student: req.user._id,
      classGroup: req.targetClass._id,
      status: 'approved',
    });
    if (!enrollment) {
      return res.status(403).json({ message: 'You are not enrolled in this class yet' });
    }
    req.enrollment = enrollment;
    next();
  } catch (err) {
    next(err);
  }
}

/**
 * Shared read access for things both roles view inside a class (quizzes,
 * materials, notices, sessions): the owning teacher, or a student with an
 * approved enrollment. Everyone else is forbidden.
 */
export async function requireClassMember(req, res, next) {
  try {
    if (req.user.role === 'teacher') {
      if (String(req.targetClass.teacher) !== String(req.user._id)) {
        return res.status(403).json({ message: 'You do not own this class' });
      }
      return next();
    }
    const enrollment = await Enrollment.findOne({
      student: req.user._id,
      classGroup: req.targetClass._id,
      status: 'approved',
    });
    if (!enrollment) {
      return res.status(403).json({ message: 'You are not enrolled in this class yet' });
    }
    req.enrollment = enrollment;
    next();
  } catch (err) {
    next(err);
  }
}

export function notFound(req, res, next) {
  res.status(404).json({ message: `Route not found: ${req.originalUrl}` });
}

export function errorHandler(err, req, res, next) {
  const status = res.statusCode && res.statusCode !== 200 ? res.statusCode : 500;
  console.error(err);
  res.status(status).json({
    message: err.message || 'Server error',
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
  });
}
